-- Application tables. Auth tables are generated by the installed Better Auth
-- version in scripts/migrate.ts. Run against the application's dedicated DB.
CREATE TABLE IF NOT EXISTS profiles (
  id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 60)
);
CREATE TABLE IF NOT EXISTS rooms (
  id text PRIMARY KEY,
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  description text NOT NULL DEFAULT '',
  topic text NOT NULL DEFAULT 'Tech',
  color text NOT NULL CHECK (color IN ('blue','violet','green','orange')),
  invite text NOT NULL UNIQUE,
  owner text NOT NULL REFERENCES profiles(id),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS members (
  room_id text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  joined_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(room_id,user_id)
);
CREATE INDEX IF NOT EXISTS members_user_idx ON members(user_id,room_id);
CREATE TABLE IF NOT EXISTS resources (
  id text PRIMARY KEY,
  room_id text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  title text NOT NULL,
  url text NOT NULL DEFAULT '',
  kind text NOT NULL DEFAULT 'Formation',
  modules jsonb NOT NULL CHECK (jsonb_typeof(modules)='array' AND jsonb_array_length(modules) BETWEEN 1 AND 150),
  due_date text NOT NULL DEFAULT '',
  created_by text NOT NULL REFERENCES profiles(id),
  UNIQUE(id,room_id)
);
CREATE INDEX IF NOT EXISTS resources_room_idx ON resources(room_id);
CREATE TABLE IF NOT EXISTS completions (
  resource_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  module_index integer NOT NULL CHECK (module_index >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(resource_id,user_id,module_index)
);
CREATE TABLE IF NOT EXISTS checkins (
  id text PRIMARY KEY,
  room_id text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  resource_id text,
  text text NOT NULL,
  link text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  approved_by text REFERENCES profiles(id) ON DELETE SET NULL,
  FOREIGN KEY(resource_id,room_id) REFERENCES resources(id,room_id) ON DELETE CASCADE,
  CHECK (approved_by IS NULL OR approved_by <> user_id)
);
CREATE INDEX IF NOT EXISTS checkins_room_date_idx ON checkins(room_id,created_at DESC);
CREATE TABLE IF NOT EXISTS reactions (
  checkin_id text NOT NULL REFERENCES checkins(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  PRIMARY KEY(checkin_id,user_id)
);
CREATE TABLE IF NOT EXISTS sessions (
  id text PRIMARY KEY,
  room_id text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  resource_id text,
  seconds integer NOT NULL CHECK (seconds BETWEEN 1 AND 86400),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(resource_id,room_id) REFERENCES resources(id,room_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS sessions_room_date_idx ON sessions(room_id,created_at DESC);
CREATE TABLE IF NOT EXISTS plans (
  id text PRIMARY KEY,
  room_id text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  title text NOT NULL,
  starts_at timestamptz NOT NULL,
  minutes integer NOT NULL CHECK (minutes BETWEEN 5 AND 240)
);
CREATE INDEX IF NOT EXISTS plans_room_date_idx ON plans(room_id,starts_at);

-- Only the server DB role accesses these tables. No public Data API policies.
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE rooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE members ENABLE ROW LEVEL SECURITY;
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;
ALTER TABLE completions ENABLE ROW LEVEL SECURITY;
ALTER TABLE checkins ENABLE ROW LEVEL SECURITY;
ALTER TABLE reactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE plans ENABLE ROW LEVEL SECURITY;
